// THE MANDATE — Literary diary entries for Chancellor Katerin Ashavel
// 52 weeks × 3+ variants each.
// Voice rules: never summarizes. Reacts. Circles. Wonders.
// Notes physical details. Refers to father. Addresses diary directly.
// Ends with something unresolved.

export interface DiaryContext {
  week: number
  flags: string[]
  economyHealth: number
  corruption: number
  publicOrder: number
  militaryReadiness: number
  pressFreedom: number
  marriageHealth: number
  lioraRelationship: number
  tomasWellbeing: number
  reformists: number
  halvekists: number
  workersCoalition: number
  ironCovenant: number
  businessClass: number
  church: number
  dravenni: number
  vaelInfluence: number
  morvecInfluence: number
  stateOfEmergency: boolean
  seridaAlive: boolean
  seridaTrust: number
  cabinetFormed: boolean
}

type DiaryEntryFn = (ctx: DiaryContext) => string

export function diaryDate(week: number): string {
  const months = ['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE',
    'JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER']
  const d = new Date(1963, 0, 1)
  d.setDate(d.getDate() + (week - 1) * 7)
  return `${months[d.getMonth()]} ${d.getDate()}, 1963 — WEEK ${week}`
}


export const DIARY_ENTRIES: Record<number, DiaryEntryFn> = {

// ─── ACT ONE: THE FIRST HUNDRED DAYS (WEEKS 1–13) ──────────────────────────

1: () =>
"I am the Chancellor of the Republic of Veltria. I have written that sentence three times and it still looks like something that belongs to someone else.\n\nThe ceremony is over. The crowds have dispersed. The palace is quieter than I expected — as though the building itself is holding its breath.\n\nVyktor left a stack of briefings on my desk. Real numbers. Not the projected ones they gave me during the campaign. The deficit is worse than they told me. So is the Tyvaren border situation. So are several other things I am not yet ready to name.\n\nMy father would not have recognized this room. He would have stood in the doorway the way he stood in the doorway of anything new — not suspicious, exactly. Just careful. He always said you should learn a room before you trust it.\n\nI don't know yet what this room wants from me.\n\nTomas asked me tonight if I was still his mama or if I belonged to the country now. I said both. He seemed to accept that. I am not sure I do.\n\nI should sleep. I won't.",

 2: (ctx) => {
  if (ctx.cabinetFormed)
    return "The cabinet is seated. The ministries are assigned. The machinery of government is beginning to move — slowly, like something rusted by two decades of neglect. Vyktor says the first week is always the hardest. He also says the second week is harder. Vyktor is not reassuring.\n\nI walked through the east gallery tonight. The portraits of my predecessors. Halvek's is still there. I stood in front of it for a full minute, trying to decide whether leaving it up was forgiveness or cowardice. I still don't know.\n\nTomas called the palace 'our new house' at dinner. Jonas didn't correct him. I didn't either. This is not our house. But for now, for however long they let me stay, it is where we sleep. That has to be enough."
  if (ctx.flags.includes('kaelen_full_promise'))
    return "I made a promise to Kaelen today. The kind of promise that either defines a Chancellorship or destroys one. Dravenni autonomy within the framework of the new constitution. He looked at me for a long time before he nodded.\n\nThe Dravenni have been promised things before. They have learned to hear promises as threats. Vyktor didn't say anything when I told him. He just wrote something in his notebook. Vyktor's silence is louder than most people's speeches.\n\nMy father's definition of democracy: 'It's not when everyone agrees. It's when everyone has a say, and then the ones who lost accept the result because they know they'll get another chance.' The Dravenni have never had another chance. I am going to give them one.\n\nOr I am going to fail them. Those are the only two outcomes."
  return "The table in the cabinet room is still empty. Nine chairs, nine folders with names written in pencil. Vyktor says we will appoint them soon, but the silence in that room is already loud. Every hour we wait, the press writes another headline about my indecision.\n\nI walked through the east gallery tonight to escape the whispers. The portraits of my predecessors. Halvek's is still there. I stood in front of it for a full minute, trying to decide whether leaving it up was forgiveness or cowardice. I still don't know.\n\nTomas called the palace 'our new house' at dinner. Jonas didn't correct him. I didn't either. This is not our house. But for now, for however long they let me stay, it is where we sleep. That has to be enough."
},

3: (ctx) => {
  if (ctx.flags.includes('bni_dissolved'))
    return "Danika Oberlin looked at me today the way people look at you when they're deciding whether you're going to be what they hoped or what they feared. I signed the dissolution order this morning.\n\nThe files are being destroyed — or they're being read, depending on who in that building I can actually trust. I keep thinking about the people whose names were in them. Some of them deserved to be there. Some of them didn't. I'll never know which is which now and that's either the right decision or a very clean way of not making one.\n\nI told myself it was the right decision. I'm still telling myself."
  if (ctx.flags.includes('bni_reformed'))
    return "The files are being audited. I'm reading them too, in the evenings. One of them is about someone I have known for fifteen years. I haven't finished reading that one yet.\n\nMy father once told me that the most dangerous thing in the world is a file that's already been opened. He was talking about something else. He was always talking about something else.\n\nI think I understand him better now. That's either wisdom or paranoia. The difference is measured in outcomes."
  return "The BNI question settled into something that was not quite an answer and not quite a decision — more like a pause that everyone agreed to call resolution. I wonder if that's what governing always is. Not choosing. Pausing with authority.\n\nI ate dinner alone tonight. Vyktor had left a note: 'Nothing urgent. Good.' That is the closest he has ever come to telling me to rest.\n\nI didn't rest."
},

4: (ctx) => {
  if (ctx.flags.includes('fiscal_austerity'))
    return "The cuts will begin next week. Vostane assures me the economy will stabilize. I have been assured of many things in the past four weeks. Some of them have turned out to be true.\n\nI keep thinking about Kravenstal. About the families Marić described — the ones making choices between heat and food. I asked myself whether I would make the same cuts if I were one of them. The answer was not the answer I wanted.\n\nThe Krone closed at 0.83 today. Vostane says that's acceptable. Her definition of acceptable and mine have diverged in ways I am only beginning to understand.\n\nI don't know what acceptable means anymore."
  if (ctx.flags.includes('fiscal_tax_wealth'))
    return "The business community is angry. Not loudly — not yet — but the kind of anger that expresses itself in cancelled meetings and redirected investment. Vostane says this was predictable. She says 'predictable' the way other people say 'inevitable.'\n\nI believe the tax increases were right. I believe it less firmly now than I said in the cabinet meeting. That's not doubt — that's honesty at a volume I can only use in this room, in these pages.\n\nTomas asked what a tax was today. I told him it was how we pay for things everyone needs. He asked if he was paying taxes. I said not yet. He seemed relieved. Then disappointed. Then he asked if I was a good person for raising taxes. I said I was trying to be a good person who sometimes had to do things that felt bad. He said: that sounds hard.\n\nIt is. He's right."
  return "The first month is almost complete. The polling numbers are good — 61%, which Vyktor describes as 'a honeymoon, not a marriage.' He is right about most things and pessimistic about the rest. It balances out.\n\nI ate dinner alone in my office. The food was cold. I was reading a report on agricultural subsidies — 47 pages on grain pricing and rural poverty. The decision it was preparing me for will affect fourteen thousand families. They will never know I read the report. They will only know whether their farms survive the winter.\n\nThat's the job. The invisible parts."
},

5: (ctx) => {
  if (ctx.flags.includes('vael_approached'))
    return "The Margrave has made contact. Not directly — Lucan Vael never does anything directly — but through an intermediary whose name I recognized and whose presence in my outer office this morning was a message in itself. Vael wants to talk about 'the Republic's economic direction.' That phrase has quotation marks around it that I can hear.\n\nI have not responded yet. The delay is itself a response — the kind he will understand. The kind that makes him nervous. I take some satisfaction in that. It is probably not a healthy satisfaction.\n\nJonas called Vael 'the shadow government' at dinner. He meant it as a joke. Neither of us laughed."
  if (ctx.workersCoalition > 60)
    return "Marić came to my office after the vote. He didn't say anything for a full minute — just stood there, breathing like a man who had been running. Then he said: 'Thank you.'\n\nGregor Marić does not thank people. He demands things from them. That is his job. The fact that he thanked me means the decision cost him more than it cost me.\n\nI should call Soraya. I will. Tomorrow. I keep saying tomorrow."
  return "The week ended quietly. That is the most dangerous kind of week — the kind where nothing happens because everything is happening underneath, in rooms I am not in, between people who are not telling me what they're deciding.\n\nI asked Vyktor if anything required my attention. He paused — Vyktor does not pause — and said: 'Nothing immediate.' The qualifier sat in the room long after he left.\n\nI worked until two in the morning. The papers were not urgent. I was avoiding something."
},

6: (ctx) => {
  if (ctx.marriageHealth < 55)
    return "Jonas didn't come to dinner tonight. He was in the guest room, reading. He said he lost track of time. He has never lost track of time in twenty years of marriage.\n\nI know what this is. I know what it means. I also know that I cannot fix it tonight and probably not tomorrow and possibly not for a very long time. That knowledge sits in my chest like something heavy that has not yet been given a name.\n\nLiora called this afternoon. She wanted to know if I was coming to her school recital next week. I said I would try. She said: 'You always say that.' She's twelve. She already knows the difference between 'I will try' and 'I will be there.'\n\nI worked until midnight. The papers were not urgent. I was avoiding the hallway."
  if (ctx.workersCoalition > 60)
    return "Marić came to my office after the vote. He didn't say anything for a full minute — just stood there, breathing like a man who had been running for a very long time. Then he said: 'Thank you.'\n\nGregor Marić does not thank people. He demands things from them. That is his job and his personality. The fact that he thanked me means the decision cost him more than it cost me.\n\nI should call Soraya. I should ask whether the coalition is actually holding or just pausing. Those are different things. The pause is what happens before the fracture. The hold is what happens when people decide to stay."
  return "The coalition is holding. That's the phrase Vyktor used. 'Holding.' Not 'thriving.' Not 'stable.' Holding. I have started to categorize all political language into two groups: things that mean what they say and things that mean the opposite.\n\nI ate dinner with Liora tonight. She told me about a boy at school who asked if her mother was a dictator. She said no, a dictator was someone who took power for themselves; her mother was given power by the people. She's twelve years old and already defending me in ways I never asked her to.\n\nThat is the thing about being a Chancellor's daughter. You inherit the enemies along with the office."
},

7: (ctx) => {
  if (ctx.flags.includes('tyvaren_publicly_condemned'))
    return "The photograph is running on the front page of every newspaper tomorrow. Dusek approved the release. She does not approve things — she states facts and lets other people make decisions. The fact that she said 'approved' means she believes this was the right call.\n\nVukov will be angry. He will deny the incident while accusing us of fabricating it. That's his pattern. The difference is that now there is a photograph and the photograph does not care about his pattern.\n\nI should feel more satisfied than I do."
  if (ctx.flags.includes('tyvaren_backchannel_used'))
    return "Three aircraft. Northern border. Colonel Dusek presented it as a test. She was right. Everything about it was a test — the timing, the altitude, the fact that they turned back before we scrambled.\n\nSomeone wanted to know how long it takes us to respond.\n\nI gave the order to stand down. Dusek agreed with me. That might mean I was right or it might mean she was waiting to see which way I'd go.\n\nThe Krone dropped 0.2 points today. Nobody mentioned it. I noticed."
  return "The Tyvaren situation has not escalated. That is the good news. The bad news is that 'not escalated' is not the same as 'resolved,' and Vukov knows the difference better than anyone.\n\nDusek briefed me on the military readiness numbers. They are lower than I would like. She said it the way she says everything — without inflection, without judgment. I have learned that when Dusek does not offer an opinion, the opinion is that the numbers speak for themselves.\n\nThey do."
},

8: (ctx) => {
  if (ctx.flags.includes('vael_dinner_charmed'))
    return "The invitation to Vael's townhouse arrived on cream-colored stationery so thick it felt like cloth. His handwriting is precise. Small. The kind of handwriting that belongs to someone who has never had to write quickly.\n\nI am going to accept the invitation. Not because I want to. Because refusing would be a statement and I am not ready to make that statement — not yet, not publicly, not without knowing exactly what it costs.\n\nThat's what governing is. Deciding which statements you're ready to make and which ones you're still pricing."
  if (ctx.flags.includes('vael_exposed'))
    return "The story ran this morning. Herald, front page. The editor called it 'a courageous stand against oligarchic influence.' The business pages called it something else. Both versions named me. Both claimed I did what I did for reasons they invented.\n\nI did it because Vael's car was parked outside my office for a week and I was tired of waiting.\n\nThat's the part they'll never print."
  return "The Archbishop's letter arrived today. Seven pages of careful theological argument wrapped around a political threat. Renek is very good at the wrapping. He has been practicing for twenty years. The congregations hear the scripture. The politicians hear the threat. Both are correct.\n\nI drafted a response. Then I wrote a different one. Then I wrote a third that says nothing and everything at once. I called my father's voice into the room the way I always do when the Church tests me. He would have said: 'You cannot out-pray a man who has made prayer a weapon.'\n\nI haven't sent the letter yet. I'll sleep on it. I say that every night. I never sleep."
},

9: (ctx) => {
  if (ctx.economyHealth < -20)
    return "Vostane's quarterly report arrived at midnight. She delivered it personally. She did not sit down. She stood next to my desk with her hands folded — Vostane never stands. She always sits, always arranges her papers. Tonight there was no arrangement. No preamble. Just a single sentence: 'I thought we had more time.'\n\nShe didn't mean weeks. She meant years.\n\nThe food on my tray went cold. I didn't notice until the cleaning staff came in at two."
  if (ctx.flags.includes('soren_immunity_revoked'))
    return "I signed the order revoking Soren's parliamentary immunity today. Theron drafted it. Theron — who has been working on the constitutional draft for months — looked at me and said: 'This is the right thing. I am not sure it is the legal thing. But it is the right thing.'\n\nGavril Soren signed execution orders during the Halvek years. One of them was for my father's closest friend. I have known this for years. I have never had the power to do anything about it. Now I do.\n\nThat is either justice or revenge. I'm not sure there's a difference."
  return "First quarter review tomorrow. I have been preparing for three days. Vyktor says preparation is not the same as readiness. He says it like it's a law of physics — something observable, true whether or not you believe it.\n\nI keep thinking about my father's last letter to me, the one he wrote before he died. 'You will be asked to make decisions that feel like choosing which part of yourself to cut off. That is not what is happening. What is happening is that you are learning which parts were never essential.'\n\nI hope he was right. I am not sure he was."
},

10: (ctx) => {
  if (ctx.publicOrder < 45)
    return "Protests in Ashenmere today. Not riots — not yet — but the kind of organized anger that knows exactly what it wants and exactly who it blames. I watched from the window. The sign-makers spelled my name correctly. That's how you know it's serious.\n\nSerida asked if I wanted the security detail increased. I said no. I said: 'They have the right to be angry at me in public.' She looked at me the way she looks at someone who might be making a mistake but hasn't made it yet.\n\nI might be making a mistake."
  return "Ten weeks. It feels like ten years. Vyktor says I am doing well for a first-term Chancellor with no prior executive experience, a hostile legislature, and an economy in transition. Vyktor says many things. Most of them are true.\n\nI ate lunch in my office today — alone, in fifteen minutes, reading a summary of the constitutional draft. Theron has written something beautiful. It will never pass in its current form. The distance between what is right and what is possible is measured in the compromises I will spend the next six weeks negotiating.\n\nJonas asked me tonight if I was happy. I said I was doing something important. He said: that's not what I asked. He's right about most things that aren't politics."
},

11: (ctx) => {
  if (ctx.tomasWellbeing < 55)
    return "Tomas asked me today if I still loved him. He is eight years old. He asked because I have missed three of his school events this month and this is how an eight-year-old processes absences — not as scheduling conflicts, but as failures of love.\n\nI held him for twenty minutes. I had a cabinet briefing at the top of the hour. I was late. I did not explain why.\n\nI am not sure how to be both of the things I am supposed to be. I am not sure it is possible. I am doing it anyway. That's either commitment or delusion and I cannot tell the difference anymore."
  if (ctx.marriageHealth > 55)
    return "Jonas made dinner tonight. Nothing elaborate — soup, bread, the kind of meal that takes twenty minutes and says more than a state banquet. We ate in the kitchen, not the dining room. He didn't ask about work. We talked about Tomas's school project and Liora's new friend.\n\nThat conversation was the most normal thing that has happened to me in eleven weeks. I almost cried — not from sadness, but from the relief of being spoken to like a person instead of a Chancellor.\n\nTomorrow I will try to do better. The trying is the only part I can control."
  return "The Kravenstal situation is deteriorating. Marić briefed me for forty minutes on the conditions in the steel collective. The numbers are worse than last month. I have three possible responses. Two will alienate the Workers' Coalition. One will alienate Vostane and the business class. There is no fourth option.\n\nVyktor brought me a list of phone calls I need to make. Eighteen names. Each one a person whose support I need for something that hasn't been announced yet. That's politics. It is not about what you believe. It is about what you can convince other people to believe long enough to get something done.\n\nThe cost is in the phone calls. The eighteen names. The people who will decide whether I succeed or fail."
},

12: (ctx) => {
  if (ctx.halvekists > 60)
    return "Kolvar gave an interview to the Thornfeld Gazette today. He called my reforms 'a betrayal of Veltrian tradition.' He used the word 'tradition' fourteen times. I counted.\n\nHe is not wrong about everything. That is what makes him dangerous — not the things he says that are false, but the things he says that are true and would be easier to dismiss if they weren't.\n\nI drafted a response. I deleted it. Vyktor said: 'Better not to respond. Let him talk. Talkers talk. Governors govern.' I kept the draft anyway. Some things you write to release, not to send."
  return "Nadia Voss requested an interview today. She wants to ask about the budget process and the BNI reforms and something she called 'the pattern of executive decisions.' That phrase is a question dressed as an observation. Nadia is very good at those.\n\nI said yes. Not because I want to do the interview but because saying no would be a story in itself and the story would be worse than whatever she writes.\n\nMy father used to say: never let a journalist define the question. If they define the question, they've already defined the answer. He was almost always right about the press. He was wrong about when to stop talking."
},

13: (ctx) => {
  if (ctx.flags.includes('no_confidence'))
    return "The vote is tomorrow.\n\nI've counted the numbers four times. They haven't changed.\n\nTonight Tomas asked me if I was going to win. I said yes. He said 'you don't sound sure.' He's eight years old.\n\nI am sure. I'm counting again."
  return "The no-confidence motion has been filed. Kolvar's speech was predictable — the Krone, the deficit, the pace of reform. What wasn't predictable was the five members of my own coalition who nodded along during the parts about 'executive overreach.' Five. That's not a rebellion. It's a warning.\n\nI called Soraya tonight. She said the Workers' Coalition was solid. I asked about the five. She was quiet for a moment. Then she said: 'Some of them are afraid. Not of Kolvar. Of their districts. Thornfeld is not Ashenmere. The Archbishop has influence there.'\n\nThe Church. It always comes back to the Church.\n\nThirteen weeks. One quarter of the year. I made a list of everything I promised during the campaign. Jonas found the list and put a glass of wine next to it. He didn't say anything. He didn't need to.\n\nThe wine is still on the desk. I am still at the desk."
},


// ─── ACT TWO: THE CONSTITUTION (WEEKS 14–26) ────────────────────────────────

14: (ctx) => {
  if (ctx.flags.includes('constitutional_convention_called'))
    return "The Constitutional Convention opened today. The Great Hall was full for the first time since the Halvek era — not with ceremony, but with argument. Theron took the floor at ten in the morning and did not yield it for forty minutes.\n\nI sat in the gallery. I watched my ministers negotiate with people who despise them. I watched Kolvar nod along to a provision about judicial independence that he will try to gut in committee. I watched Kaelen take notes on a clause that might change two hundred thousand lives.\n\nThis is what democracy looks like. Not the speeches. The minutes between them — the quiet conversations in the corridors, the compromises scribbled on napkins, the things people agree to when they think no one is watching."
  if (ctx.flags.includes('elena_ally'))
    return "Elena is in. She has agreed to support the reform agenda through the Dispatch's editorial board. I have known Elena since university. We were friends. Then we were something more complicated. Now we are Chancellor and editor and the distance between those two things is filled with the unspoken understanding that either of us could hurt the other if we chose to. We are choosing not to. For now.\n\nShe asked me at the end if I was okay. The question was not professional. I said I was fine. She said: 'You were always a terrible liar.'\n\nSome friendships survive power. Most don't."
  return "Two weeks into the constitutional process and I am already exhausted. Not by the work — the work I expected. By the pace at which people who agreed with me six months ago are now discovering reasons to disagree. Every provision has an opponent. Every compromise has a cost. Every ally is also a potential adversary.\n\nVyktor brought me a chart tonight that mapped the factions across twelve key provisions. The chart looked like a spider web drawn by someone who was angry. There is no majority for any single vision. There are only temporary coalitions that shift depending on which paragraph is being debated.\n\nThat is democracy. It is messier than I expected and more exhausting than I prepared for and it is also the only thing standing between this country and the kind of government where one person decides everything and everyone else pretends to agree."
},

15: (ctx) => {
  if (ctx.flags.includes('theron_full_vision'))
    return "Theron submitted his full constitutional draft today. Four hundred pages. I read the preamble three times. It begins: 'We, the people of the Republic of Veltria, having endured the darkness of tyranny and the uncertainty of transition, do hereby establish this Constitution as the supreme law...'\n\nHe wrote that alone, at three in the morning, after a day of negotiations that had left him looking ten years older. Trust is not given. It accumulates — the way paperwork accumulates on a desk, one document at a time.\n\nHe said one more thing before he left: 'If this fails, it will not be because we didn't try hard enough. It will be because we tried at all.' I think that was meant to be comforting. I'm not sure it was."
  if (ctx.flags.includes('constitution_compromise_security'))
    return "I made a deal with Kolvar's bloc on the national security provisions. The constitution will retain limited emergency powers — more limited than Kolvar wanted, less limited than Theron wanted.\n\nTheron was quiet in the meeting. Not angry — disappointed. The disappointment is worse than the anger. Anger you can argue with. Disappointment just sits in the room like something heavy.\n\nI asked if the imperfections were survivable. He said: 'We won't know for twenty years.' Twenty years. I will be sixty-seven. He will be eighty-two. We will know by then whether the compromises we made today held the country together or tore it apart."
  return "The convention is in its third week. The factions are digging in. Kolvar's people want more executive power. Brenner's people want military autonomy. The Church wants religious education protected. The Dravenni want language rights. Every demand is reasonable from the perspective of the people making it. Every demand is incompatible with at least two other demands.\n\nI spent four hours today in a room with the negotiation teams. We got through three articles. Two of them will need to be reopened tomorrow because someone changed their mind overnight.\n\nMy father once said: 'Anything worth building takes longer than you think it should. If it were easy, someone would have done it already.' He was always right about things that took time."
},

16: (ctx) => {
  if (ctx.flags.includes('kolvar_deal_struck'))
    return "I struck a deal with Kolvar today. Thirty Halvekist votes in exchange for a modified emergency powers provision. Vyktor called it 'a necessary evil.' Theron called it 'a Devil's bargain.' Both of them are right.\n\nThe provision as amended preserves the Chancellor's authority for 90 days — renewable by parliamentary vote. Kolvar wanted 180 days with no oversight. I got him down to 90 with a supermajority requirement. That is either a victory or a defeat depending on which side of the table you're sitting on. I am sitting on both sides."
  return "The convention is at an impasse. Two days of negotiations on judicial independence and we are exactly where we started. Kolvar wants the Chancellor to appoint judges. Theron wants an independent commission. The compromise has been rejected by both sides as 'worse than either alternative.'\n\nI spent the evening reading the draft again. There are provisions in it that would have seemed radical five years ago. Provisions my father would have wept to see.\n\nI need to find eight more votes. Eight. Out of 250. Four percent of the Assembly that decides whether this country has a constitution."
},

17: (ctx) => {
  if (ctx.flags.includes('accountability_provision_passed'))
    return "The accountability provision passed today. Narrowly — 134 to 116 — but it passed. Gavril Soren can no longer hide behind parliamentary immunity. The crimes of the Halvek era will have their day in court.\n\nTheron was crying in the gallery. I have never seen Theron cry before. He was not weeping for joy — he was weeping because he knows what it cost and what is still coming.\n\nI did not cry. I have been waiting for this moment since my father's funeral. The man who signed the execution order for his best friend is finally going to face justice. I should feel something. I feel tired.\n\nMaybe justice is not something you feel. Maybe it's just something you do."
  if (ctx.flags.includes('church_deal_rejected'))
    return "I rejected the Church's proposal today. Renek wanted the constitution to recognize Veltria as 'a nation under divine guidance.' I said no. He did not raise his voice. He did not need to. The quiet was the threat.\n\nThe Church runs more hospitals than the state. It educates more children than any three private academies. Two million Veltrians attend services weekly. Rejecting Renek's proposal is not a legal decision. It is a political decision that will cost me every rural district from Thornfeld to Gravenmark.\n\nI did it anyway. The constitution must speak to all Veltrians — believer and atheist, city and countryside. That was the promise I made. Keeping promises is more expensive than anyone tells you."
  return "Kolvar's bloc walked out of committee today. Thirty members. They left their notes on the table — a symbolic gesture, the kind that photographs well and means nothing legally but everything politically.\n\nVyktor says they'll be back. He says walkouts are tactical, not strategic — a way of signalling to their base before accepting a compromise. I asked how he knew. He said: 'Because I have walked out of committee sessions. Everyone has. It is the parliamentary equivalent of slamming a door.'\n\nThe vote is in nine days. Nine days to bring them back or find the votes elsewhere."
},

18: (ctx) => {
  if (ctx.flags.includes('vael_fund_invested'))
    return "I accepted Vael's investment fund this afternoon. The paperwork is twenty-two pages. The fund will finance infrastructure in the northern provinces — schools, roads, a hospital in Kravenstal that the state cannot afford. Real people will benefit. That is the justification.\n\nVael did not become the wealthiest man in Veltria by funding hospitals out of generosity. There will be a price. There is always a price. I just don't know what it is yet.\n\nMy father would have told me to walk away. My father was also never responsible for a budget deficit that threatens to collapse the Krone. Context matters. Context is also an excuse."
  if (ctx.flags.includes('stood_up_to_vael'))
    return "I declined Vael's offer today. Politely, publicly, with the kind of diplomatic language that makes a refusal sound like a principled stand. Vyktor drafted the statement. I revised it. Three sentences that took two hours to write.\n\nVael's response arrived within forty-five minutes — a handwritten note expressing 'disappointment' and 'hope for future opportunities.' The markets dipped slightly in the afternoon. Someone leaked the news before my statement went out.\n\nThe leak is the message. The message is: declining Vael has consequences, and the consequences begin before you've even finished declining."
  return "The autumn festival was today. I walked in the parade — not at the front, where Chancellors usually march, but in the middle, with the workers from the textile collective. Marić arranged it. He said: 'They need to see you with them, not above them.'\n\nA woman handed me a winter rose. She said: 'Don't give up.' I said I wouldn't. She said: 'They always say that.'\n\nThe flower is on my desk. It is wilting. They do that."
},

19: (ctx) => {
  if (ctx.flags.includes('refugee_policy_open'))
    return "Ten thousand people crossed the Dravenni border this week. Families. Children. People who left everything because staying was worse than leaving.\n\nI opened the border. Kolvar called it 'a security risk.' Brenner called it 'a logistical challenge.' Both were right and both were wrong about what matters. What matters is that ten thousand people are sleeping in camps tonight who were sleeping in houses last week.\n\nThe camps are at 80% capacity. Winter is coming. I need to find more resources by Friday."
  if (ctx.marriageHealth < 50)
    return "Jonas and I had our first real fight tonight. Not about politics — about us. He said: 'You chose the country. I understand that. But I didn't choose for you to stop being my wife.'\n\nHe was right about everything. That is what made it a fight instead of a conversation — he was right and I knew he was right and I still could not give him what he was asking for.\n\nThe hours I have for him are the hours left over after the country takes what it needs. The leftovers are not enough for a marriage.\n\nHe slept in the guest room. I didn't sleep at all."
  return "Liora asked me tonight what was happening to the refugee children. She has a friend whose family came from Morivask. I told her we were doing everything we could. She said: 'That doesn't sound like enough.' She's right.\n\nThe gap between 'everything we can' and 'enough' is where most of my decisions live. The gap is wide. It's getting wider."
},

20: (ctx) => {
  if (ctx.flags.includes('budget_crisis_resolved'))
    return "The budget crisis has been resolved. Or rather, postponed with a framework that might hold for six months if the economic projections are accurate and the IMA agrees and the Assembly doesn't force another round of cuts. That's three 'ifs.' Three too many.\n\nVostane presented the revised numbers. No one got everything they wanted and everyone got enough to survive. That is either good governance or collective failure. I can't tell the difference anymore.\n\nVyktor left a note: 'The numbers work. The politics will follow. The politics always follows.' I am not sure I believe the second sentence."
  if (ctx.flags.includes('vael_fund_invested_hidden'))
    return "I invested Vael's money into three projects today. The paperwork is buried in the budget appendix — not hidden, but placed where only people who read every line will notice.\n\nThe projects are real. Roads will be built. Schools will open. The children who attend them will not know or care where the money came from. That is either the justification or the excuse.\n\nMy father would have called this corruption. My father was never responsible for a budget deficit. Context matters. Context is also an excuse. I can't tell which one this is."
  return "Twenty weeks. The midpoint is approaching. I can feel it — a pressure in the air that wasn't there before. The decisions I make now define the second half of the term.\n\nI made a list of everything I promised during the campaign. I crossed off the things I've done — fewer than I hoped. I circled things I still intend to do — more than I have time for. I drew a line through the things that were never realistic — the promises you make because you want to believe them.\n\nThe line went through more items than I expected. That's either honesty or failure."
},

21: (ctx) => {
  if (ctx.flags.includes('superpower_aligned_arcturian'))
    return "I have chosen. The Arcturian path. Stellamere. Democracy and trade and the kind of alignment that comes with the expectation that you will vote the right way at international forums.\n\nThe Orythian ambassador is still in Ashenmere. He has not asked for another meeting. He is waiting for me to ask. I will not ask but I will wonder — probably for the rest of my life — whether the other path would have been better. You only get to know one outcome. The other one remains a possibility, perfect and unrealized.\n\nMy father distrusted the Arcturians — said they exported democracy with a gun in one hand and a contract in the other. But my father never had to govern."
  if (ctx.flags.includes('superpower_aligned_orythian'))
    return "I chose Orythia. Petravar. The fraternal handshake and the military coordination pact. Ambassador Stahl was not gracious. He was satisfied. There is a difference.\n\nThe Arcturian ambassador issued a statement expressing 'concern.' That is diplomatic language for 'we will remember this.' The IMA is an Arcturian institution in all but name. This choice will have consequences for the next loan negotiation.\n\nI made the choice I thought was right for Veltria. Whether I was right will be determined by events I cannot control — Tyvaren troop movements, Orythian reliability, the patience of a superpower whose promises have a limited shelf life."
  return "The superpower alignment question has been deferred. I could not choose — not yet, not without knowing what the constitutional referendum will bring. Both ambassadors were told: Veltria will decide its foreign policy on Veltrian terms.\n\nNeither of them believed me. The Arcturian smiled in the way that means 'we will wait.' The Orythian did not smile at all.\n\nThe middle path is the hardest one. You don't get the benefits of either alignment and you incur the suspicion of both. But you also keep something neither superpower can offer — the freedom to make decisions not pre-approved by a patron.\n\nThat freedom is expensive. I will find out exactly how expensive in the weeks ahead."
},

22: (ctx) => {
  if (ctx.flags.includes('ssd_first_report_complete'))
    return "The Special Security Directorate submitted its first report. Branek is cooperating — that means naming names in exchange for a reduced sentence. The names are people I know. Three I promoted. Two I defended in cabinet. One I considered a friend.\n\nI read the list twice. Some of these people have been attending my briefings for months, nodding along to things I said about accountability. The betrayal is not surprising — corruption was the operating system of the Halvek regime — but the specificity is hard to process.\n\nI haven't decided what to do with the list. Release it and destabilize the government before the referendum. Sit on it and become the thing I campaigned against."
  if (ctx.corruption < 45)
    return "The BCA investigation is producing results. Seventeen officials flagged for review. Department heads, procurement officers, one deputy minister whose name I will not write here because writing it would make it real in a way I am not ready for.\n\nOberlin brought me the preliminary findings. She said: 'The system is cleaner than it was. It is not clean.' I asked how long until it was clean. She said: 'A generation. Maybe two. Corruption is a condition you manage, not a problem you solve.'\n\nA condition. Like a chronic illness. Something you treat but never cure."
  return "Nadia Voss's investigation is accelerating. Three more records requests this week. Her questions are becoming more specific — no longer asking 'what happened' but 'who knew and when did they know.' The difference is the difference between journalism and prosecution.\n\nI have not interfered. But I watch the process the way you watch a fire burning toward something you care about.\n\nVyktor says Nadia is doing her job. I asked if her job was dangerous for us. He said: 'Truth is always dangerous for someone.' I don't know the answer. Neither does he."
},

23: (ctx) => {
  if (ctx.flags.includes('liora_archive_resolved'))
    return "Liora found the archive. She has been searching for months — ever since her first records request about her grandfather. The file confirms what we suspected: Mikhael Ashavel was executed on Halvek's orders. The signature is Gavril Soren's.\n\nShe came to my office holding the file like something that might break. She said: 'You knew.' I said I suspected. She said: 'Suspected is not the same as knowing.' She's right. Suspected is what you carry in your chest for years. Knowing is a door that opens and cannot be closed.\n\nWe sat together for an hour. We talked about her grandfather — the things I remembered, the things she had only heard about. A man who kept candy in his pockets. A man murdered for believing in a different Veltria.\n\nLiora is fifteen. She knows things I wanted to protect her from. I couldn't protect her. I'm not sure I should have tried."
  if (ctx.flags.includes('tomas_nationalist_challenged'))
    return "The headmaster called again. Tomas was not in class. He was at the switching yards north of Ashenmere — the same older boys, the same dangerous proximity to trains and to ideas that are older and harder than anything I want my son to believe. The Iron Covenant recruits near the yards. Recruiting. Grooming. Both words mean the same thing.\n\nI picked him up myself. Not a staff car — my own car, the one I drove before. He was quiet. Then he said: 'They say you're destroying Veltria.' I asked who. He didn't answer. He didn't need to.\n\nI told him they were wrong. He said: 'They sound like they believe it.' That's the hardest part. They do believe it."
  return "The family is holding. Barely. Jonas has started leaving notes again — small things, reminders. The notes are not warm but they are present. Presence is a form of hope.\n\nTomas came home on time today. Liora ate dinner with us. She asked if I was going to win the referendum. I said I didn't know. She said: 'You say that a lot now.' She's right.\n\nThere is a kind of honesty that sounds like weakness. There is a kind of confidence indistinguishable from delusion. The space between them is where I live now."
},

24: (ctx) => {
  if (ctx.flags.includes('brenner_warning_received'))
    return "General Brenner requested a private meeting today. In the General Staff Wing. He used language carefully — 'institutional concerns,' 'constitutional continuity,' 'the military's role in democratic transition.' Every phrase was precise. Every phrase was also a threat dressed in uniform.\n\nHe did not say the military would intervene. He did not need to. The implication was in the location — where no Chancellor has been since Halvek — and in the silence of the colonels who watched me walk down the corridor.\n\nDusek was waiting when I returned. She said: 'The officer corps is divided. I am not the one you need to worry about.' I haven't told anyone about this meeting. I am telling you, diary, because someone needs to know."
  if (ctx.flags.includes('brenner_accommodation_signaled'))
    return "I sent a signal to Brenner through Dusek. The military's institutional concerns will be heard. Provisions protecting the armed forces from political interference. In exchange, the General Staff will publicly support the constitutional process.\n\nThe deal is quiet. If the reformists find out I negotiated with Brenner behind closed doors, the coalition fractures. If I don't negotiate, the military's silent opposition could sink the referendum.\n\nThese are the choices they don't teach in political theory. The theory assumes you have power. The practice is about what you give up to keep it."
  return "Twenty-four weeks. Half the mandate. Vyktor left a single sheet on my desk: 'Tasks completed: 34. Deferred: 22. Impossible: 6.' He didn't explain. He knows I know.\n\nThe thirty-four are what I will campaign on. The twenty-two are what I will apologize for. The six are what I will carry for the rest of my life.\n\nI walked through the east gallery tonight. Chancellor Marek. Chancellor Voronin. Chancellor Halvek. Three faces. Three legacies. One destroyed the country. One rebuilt it. One is still being judged. I will join them on this wall someday."
},

25: (ctx) => {
  if (ctx.flags.includes('referendum_last_move_public'))
    return "Tomorrow the country votes. I gave a television address — three minutes, timed to the second. I told them what the constitution meant. Not the legal language — the human language. A woman whose father was killed by a system that answered to no law. A mother whose children will grow up in a different Veltria if this document passes.\n\nThe studio was cold. The lights were hot. My hands were steady. They always are steady when it matters. The trembling comes later.\n\nThe numbers are close. Vyktor says 52-48. Four points either way.\n\nI should sleep. I won't. I never sleep the night before something that matters."
  if (ctx.flags.includes('kolvar_deal_rejected'))
    return "I rejected Kolvar's final offer tonight. He wanted the emergency powers expanded and the accountability clause weakened. In exchange, his thirty votes. I said no.\n\nThe no felt different from other nos. It felt like the first decision in weeks that was not a compromise. Just a line drawn because I could not live with what would happen if I didn't draw it.\n\nVyktor said I was making a mistake. He said he thought I was right but being right would cost me the vote. If the referendum fails, it will fail because I was not willing to trade accountability for votes. That is either the most principled decision I've made or the most self-destructive."
  return "The final polling arrived at eleven tonight. Vyktor brought them on foot rather than by telephone. That's how you know the news isn't good.\n\nJonas was in the room. He didn't say anything. He just put his hand on my shoulder. That gesture — that simple physical presence — was more comforting than any briefing I've received in six months.\n\nWe talked about Tomas's school project and Liora's new interest in botany. For forty minutes, I was not the Chancellor. I was a wife and a mother and a person not yet defined by whether the constitution passed.\n\nForty minutes. It was not enough. It was what I had."
},

26: (ctx) => {
  if (ctx.flags.includes('referendum_won_decisive'))
    return "Sixty-point-seven percent. The constitution passed. Dravenhollow 84 percent. Kravenstal 61. Even Thornfeld — which I was told to write off — came in at 53.\n\nTheron was in the counting hall. He didn't cheer. He stood very still with his hands at his sides and then closed his eyes for a long moment. I think he was praying.\n\nJonas held my hand under the table. He said: 'You did this.' I said: 'We did this.' He said: 'You. Let yourself have it.' I am letting myself have it. For tonight. Tomorrow the implementation begins and the opposition regroups. But tonight, for the first time in twenty-six weeks, I am certain I did something right."
  if (ctx.flags.includes('referendum_won_narrow'))
    return "Fifty-one-point-eight percent. Passed by fewer than thirty thousand votes. A margin so narrow that Kolvar has already filed challenges in three provinces.\n\nThe constitution is law but it is law that half the country believes was imposed on them by a government they don't trust. I won the vote but I'm not sure I won the argument.\n\nThe difference between those two things is the difference between a constitution that lasts fifty years and one repealed the moment the opposition takes power. I have to make sure it lasts."
  return "Forty-six-point-three percent. The constitution did not pass.\n\nI called Theron at two in the morning. He was still in his office, reading the draft as though preparing for a revision that will never come. He said: 'We tried.' I said: 'Trying is not enough.' He said: 'It never is. But it's what we have.'\n\nI don't know what happens now. The coalition will fracture. Kolvar will demand my resignation. But I am still Chancellor. I am still here. The mandate is damaged but not gone.\n\nTonight I am letting myself feel the loss. The thing I wanted most. Failed. Not because I was wrong about Veltria. Because I could not convince enough people I was right."
},


// ─── ACT THREE: THE CRUCIBLE (WEEKS 27–39) ──────────────────────────────────

27: (ctx) => {
  if (ctx.flags.includes('referendum_won_decisive') || ctx.flags.includes('referendum_won_narrow'))
    return "The first morning after the constitution. The palace feels different. Lighter — not because anything has physically changed, but because the weight of uncertainty has been replaced by the weight of responsibility. The second weight is heavier. It is also cleaner.\n\nThe morning briefing was shorter. Vyktor had prepared three scenarios for the post-referendum landscape. Now there is only one. He seemed almost disappointed. Vyktor is most comfortable preparing for disasters. Peace makes him nervous.\n\nCabinet met at ten. Vostane presented the implementation budget — forty million ₭ over two years. The money exists on paper. It does not exist in the treasury. The gap is where the next crisis will come from."
  return "The constitution failed. The headlines this morning are brutal — some gleeful, some mournful, all asking: what now?\n\nI addressed the cabinet for twenty minutes. I said the things a leader is supposed to say. I believed about half of what I said. The half I didn't believe was the half that matters most.\n\nTonight I sat and looked at the clock — the same clock that has been on my desk since the first week. It has ticked through every crisis and every victory. It does not care about any of them. It just keeps ticking.\n\nTomorrow I will do what the clock does. Keep ticking. That is the only option."
},

28: (ctx) => {
  if (ctx.economyHealth < -25)
    return "The Krone is falling. The IMA representatives arrived at the Finance Ministry at four in the morning without announcement. They do not announce these visits. They simply appear, like auditors in a nightmare.\n\nThe conditions will be presented tomorrow. I already know what they'll contain: job cuts, privatization, austerity that hits the provinces hardest. The provinces that voted for me. I'm about to prove them wrong in the most painful way — making the same choices as my predecessors, for different reasons.\n\nVyktor says there's no alternative. I asked if there was any way out. He was silent for a long moment. Then he said: 'There are always ways out. The question is whether the ways out are worse than the corner.' That sentence has been circling in my head all day."
  if (ctx.economyHealth > -10)
    return "The economy is stable. Vostane's word: 'stable.' She said it the way a doctor says a patient is stable after surgery — not better, but not deteriorating. The IMA sent a courtesy message rather than an ultimatum. A courtesy message from the IMA is the diplomatic equivalent of a standing ovation.\n\nI should be relieved. But stability is not growth and people didn't vote for stability. They voted for change. Stability means things have stopped getting worse but not started getting better. The distance between 'not worse' and 'better' is the distance between reelection and defeat.\n\nVostane says growth will come in eighteen months. The election is in twenty-four weeks. The math does not work."
  return "The post-referendum cabinet met today. Two ministers sent deputies. One sent no one. The empty seats were louder than the filled ones.\n\nSome of the people who were with me in January are now calculating whether being with me in March is still in their interest. I can feel the calculations happening. I just don't know the results yet.\n\nVyktor says this is normal after a major vote. He says the reassessment period is dangerous but survivable. I asked how long it lasts. He said: 'Until the next vote.' There is always a next vote."
},

29: (ctx) => {
  if (ctx.flags.includes('vyktor_exposed'))
    return "The Dispatch ran the story this morning. Front page. Vyktor Reznik's BNI past — the surveillance, the files, the decades. Nadia Voss's byline.\n\nVyktor came to my office at seven. His face was different from any face I've seen him wear. He said: 'You deserve a debrief.' I said I already knew most of it. He said: 'You know what Nadia found. You don't know the rest.'\n\nHe told me the rest. It took forty minutes. Some of it I suspected. Some of it I had not. Vyktor does not lie — not to me. He withholds and he frames and he presents information in the order that produces the response he wants. But he does not lie.\n\nI have not decided what to do. I cannot fire him. I cannot ignore the story. The space between those two impossibilities is where I have to live."
  if (ctx.flags.includes('vyktor_tipped_off'))
    return "I told Vyktor about the story before it ran. He came at midnight and I told him what Nadia had found. He did not react — Vyktor never reacts to bad news. He processes it, categorizes it, begins constructing a response before the news has finished being bad.\n\nHe said: 'I will handle this. You will be kept separate.' I asked what he was going to do. He said: 'Whatever is necessary.' That phrase — precise, ambiguous, carrying decades of experience navigating systems designed to destroy people like him.\n\nLosing him would be a blow. Protecting him would be a scandal. Those are the only two doors."
  return "The weeks are blurring together. Someone asked me what day it was and I couldn't remember. The days are defined by briefings and crises.\n\nI ate breakfast standing up. Toast. Cold coffee. I was reading a report while I ate, so it doesn't count as a meal. Meals are supposed to happen when you're not doing other things. I haven't had one in months.\n\nThe palace at night is different from during the day. Quieter. More honest. The portraits seem to watch you more closely after midnight. The silence is full of everything that happened here before I arrived and everything that will happen after I leave."
},

30: (ctx) => {
  if (ctx.seridaAlive && ctx.seridaTrust > 60)
    return "Serida knocked on my door at eleven tonight. She was holding a photograph. A young man in military uniform. She said: 'I have never shown this to anyone.' Her brother. Volen. Nineteen when the BNI arrested him in 1958.\n\nI have known Serida for three years. She has never mentioned him. Some silences are not secrets — they are things too heavy to carry in conversation.\n\nShe opened the drawer tonight. She told me about the arrest and the trial that never happened and the letter saying he had been 'transferred' — that bureaucratic evasion, that way of saying someone is gone without admitting you made them gone.\n\nI asked what she wanted. She said: 'I just wanted someone to know his name.' I will know his name. Volen Valk. That is the least I can do. That is also, in some ways, the most."
  if (ctx.flags.includes('vostane_defected'))
    return "Vostane appeared on television standing next to Kolvar. Reading a prepared statement. She called my policies 'unsustainable' and 'detached from fiscal reality.' She used 'regrettably' four times — the shield you deploy when you're about to do something you know is wrong.\n\nI watched from my study. Vyktor said: 'This was always a possibility.' I asked why he hadn't warned me. He said: 'I did. Six weeks ago. You said Vostane would never do it.'\n\nHe was right. I believed it. I was wrong.\n\nThe Finance Minister of the reform government has defected. The markets will react tomorrow. The no-confidence motion will suddenly have more votes.\n\nI trusted her. Trust is a memory you cannot unmake."
  return "Colonel Dusek arrived at my office in civilian clothes. I have never seen Irina Dusek out of uniform. She looked smaller without the insignia. She was holding a folder she did not open.\n\nShe said: 'There are officers who are not loyal to the constitution.' I asked how many. She said: 'Enough.' The word sat in the room like something heavy.\n\nI asked if she was one of them. She looked at me for a long moment. Then she said: 'I am in your office at eleven at night warning you about them. What do you think?'\n\nI think she is loyal. I think she is also afraid. Those two things are not contradictory. That's what courage looks like — not absence of fear, but the presence of something you believe in more."
},

31: (ctx) => {
  if (ctx.stateOfEmergency)
    return "The emergency provisions are in effect. I signed the order this morning. Dusek was in the room. Vyktor was in the room. Neither told me to do it. Neither told me not to.\n\nNobody tells you to use emergency powers but nobody stops you either. Everyone waits to see what you do and judges whether you were right based on outcomes that haven't happened yet.\n\nI can feel the weight of the signature. Not on the paper. On my hand. On my conscience. On the version of myself that existed before I knew what it felt like to suspend the constitution I spent months trying to build.\n\nI told myself it was necessary. I told myself the threat was real. Both are true. Neither makes me feel better."
  return "The inner circle is shrinking. People who were in this office six months ago are gone now. Vostane. Possibly Vyktor. Others whose names I won't write here.\n\nThe morning briefing is shorter. Fewer arguments. Less noise. The silence is not efficient. The silence is the sound of people leaving.\n\nTheron is still here. Dusek is still here. Soraya is still here. The ones who stayed believe in the project more than their careers. I need to remember that. I am trying to convince myself of it. The convincing is not quite working."
},

32: (ctx) => {
  if (ctx.flags.includes('tyvaren_ultimatum'))
    return "Marshal Vukov has issued an ultimatum. Cede Gravenmark Pass or face 'consequences.' Seventy-two hours.\n\nThe clock on my desk has never been louder.\n\nDusek briefed me on the military options. All of them involve people dying. The question is how many and whose. That is the math they teach in staff colleges — the calculus of acceptable losses. My father said once you start calculating acceptable losses, you've already lost something essential. He was right. He was also never responsible for the defense of a nation.\n\nI have already decided. I am using the remaining hours to find the courage to say it out loud."
  if (ctx.flags.includes('tyvaren_diplomacy_initiated'))
    return "I chose diplomacy over confrontation. The Foreign Minister is en route to Strevna. The Tyvaren delegation arrives within twenty-four hours. Exploratory talks — but it is more than we had yesterday.\n\nDusek was opposed. Brenner was opposed. The military wanted a show of force and I gave them a negotiating table. The table is not impressive. The table does not deter anyone. But as long as people are sitting at it, they are not shooting.\n\nI don't know if the negotiations will succeed. The Arcturians have offered 'support for the diplomatic process' — that phrase, that careful non-commitment. The Orythians have offered nothing. They are waiting to see which way the wind blows."
  return "Thirty-two weeks. I can feel the weight of them like accumulated fatigue — not in any single moment, but in the background, a hum that never stops.\n\nI slept four hours last night. More than I've slept all week. I should feel rested. I feel like I borrowed the sleep from somewhere I haven't paid back yet.\n\nThe palace garden is blooming. I noticed this morning — the winter flowers replaced by spring ones. The gardeners changed them without my noticing. Things happen in this building I don't know about. That used to bother me. Now it feels like mercy."
},

33: (ctx) => {
  if (ctx.flags.includes('soren_files_revealed'))
    return "The crate was mislabeled. That's the detail I keep coming back to. 'Personnel Records — 1957-1959.' It was not personnel records. It was execution orders. Signed. Stamped. Filed like paperwork.\n\nSoren's signature is on forty-two of them. One is the order for Mikhael Dorne — my father's closest friend. Dated March 14, 1958. Reason: 'sedition.' Typed. The signature is pen.\n\nI have been holding this for six hours. I haven't decided what to do. Prosecution will tear the country apart. Suppression makes me complicit. There is no clean path — only different kinds of damage.\n\nThe crate is in a secure room. I have ordered it guarded. I don't know who I'm guarding it from. The people who want it destroyed are the people supposed to protect it."
  if (ctx.militaryReadiness > 50)
    return "I have authorized partial mobilization. Dusek's staff is coordinating with provincial commanders. The Tyvaren ultimatum clock is still running.\n\nThe logistics are moving. That's the phrase Dusek used. It means soldiers are leaving their bases. Families are saying goodbye. Behind those three words are ten thousand human stories I will never hear.\n\nI keep thinking about the families. The wives. The children. The parents who will receive letters or telegrams depending on outcomes I am deciding right now. My father would have said leadership means carrying the weight of those letters even if you never read them. Especially if you never read them."
  return "The war preparations continue. The border is quiet — quieter than it has been in weeks, which Dusek says is a bad sign. Quiet borders in the Tyvaren theater usually mean forces are being repositioned.\n\nI authorized the first round of rationing protocols. The economy can sustain a short conflict. A long one will require borrowing that takes a generation to repay.\n\nA generation. Tomas's generation. Liora's. The one I'm supposed to be building a better country for. If there is war, it won't matter what the constitution says. It will matter who wins."
},

34: (ctx) => {
  if (ctx.flags.includes('military_deployed'))
    return "The first units are in position. Twenty thousand soldiers along the northern border. Another ten thousand in reserve. Numbers large enough to deter, small enough not to be interpreted as a declaration of war.\n\nBrenner has been quiet since the deployment order. Not hostile — quiet. The kind of quiet that means he is watching. His loyalty has always been to the military first and the government second. In a crisis, the gap between first and second becomes visible.\n\nWe are not discussing it because discussing it would make it real. The silence is the strategy."
  if (ctx.dravenni > 50)
    return "Kaelen sent another message today. Three this week. Each shorter than the last. The third was two sentences: 'We need to know where we stand. The time for patience is over.'\n\nThe Dravenni have been patient. More patient than I had any right to expect. I promised them autonomy twenty weeks ago. Implementation has been delayed by the Tyvaren crisis and the budget and the dozen other emergencies.\n\nThese are reasons. Reasons are not excuses. The distinction matters to the Dravenni, who have heard a lifetime of reasons why their rights could be recognized next year. Eventually.\n\nEventually is a word that means never in the language of minority rights."
  return "The Dravenni situation is deteriorating. The Liberation Front has made contact through intermediaries — they want to know whether Veltria will honor autonomy or suppress it. 'Honor or suppress.' Those are the only two verbs they believe are available.\n\nCholera in two refugee camps. Seven dead. The numbers are small but the numbers are people and every Dravenni death is a statement whether I intend it or not.\n\nI need to close the space between what I promised and what I've delivered. I don't know how."
},

35: (ctx) => {
  if (ctx.marriageHealth < 40)
    return "Jonas has stopped waiting up. I came home at midnight and the lights in the residence were off — all of them. He used to leave one lamp on. The lamp was dark tonight.\n\nI stood in the bedroom doorway for a long time. He was asleep. Or pretending. The difference doesn't matter. What matters is he stopped leaving the light on and I don't know when because I haven't been coming home early enough to notice.\n\nThe marriage is not over. But it is not what it was. It is something held together by children and history and the knowledge that neither of us knows what would happen if we let go.\n\nI should talk to him. I should say: I am afraid and I am tired and I am failing at half the things I care about and that half includes you. I should say that. I won't."
  if (ctx.flags.includes('nadia_cooperated'))
    return "Nadia published the second investigation. Not the BNI story — a different one. The budget process. The off-the-books transfers. The headline: 'The Chancellor's Invisible Budget.'\n\nI cooperated on this one. Vyktor told me it was a mistake: 'Never let a journalist define your narrative.' I said the narrative was already defined. The question was whether I got to shape it.\n\nThe article is critical but not hostile. It acknowledges constraints and emergencies. It also asks pointed questions. The questions are fair. They are also damaging. Sometimes all the choices are wrong and you just pick the one that's wrong in the right way."
  return "I keep having the same nightmare. Standing at a podium in front of a crowd and opening my mouth and no sound coming out. The crowd starts to leave — not angry, disappointed. The disappointment is worse.\n\nI told Serida about the dream. She said: 'Everyone who has held this office has had that dream. The ones who stop having it are the ones you should worry about. It means you still care.'\n\nThe dream bothers me. I am taking that as a good sign."
},

36: (ctx) => {
  if (ctx.seridaAlive && ctx.seridaTrust > 50)
    return "Someone tried to kill me today. The words look absurd on the page — like a novel, not a diary. But it happened. A noise in the crowd. Something metallic. Serida was faster than the assassin.\n\nI keep replaying it. She didn't hesitate. She moved toward the threat, putting herself between me and the person who wanted me dead.\n\nJonas held me for twenty minutes when I got home. He didn't ask questions. He just held me. The most generous thing anyone has done for me since I took this job.\n\nI am alive. That should feel like something. It feels like a blank space where an emotion should be. I think that's shock. I think it will pass."
  if (!ctx.seridaAlive)
    return "Serida is dead. The bomb was in the press gallery. She was standing where I was supposed to be standing. A schedule change saved my life — a staffer who rescheduled the briefing without informing security. That oversight killed Serida.\n\nI hired her three years ago. She was twenty-six. The best security chief the Chancellery ever had. Kind in ways that surprised me — the way she talked to Tomas, the way she noticed when I hadn't eaten.\n\nTomorrow I will appoint her replacement. I will brief the cabinet and address the press and pretend the machinery of government continues. But tonight — for these minutes — I am writing about Serida Valk. About the photograph she carried. About her brother Volen. About the way she always used the full title: 'Chancellor.' She believed the office deserved the full word.\n\nShe was thirty years old. The bomb was meant for me."
  return "The investigation continues. Dusek is leading it personally. I told her I wanted the truth, whatever it was. She said: 'The truth is always complicated. Are you prepared for complicated?' I said I was. I wasn't sure.\n\nTomas asked if the person who tried to hurt me was bad. I said yes. He asked why someone would want to be bad. I didn't have an answer. He said: 'That doesn't make sense.' He's right.\n\nI am alive. The country is still functioning. The continuation is what I have."
},

37: (ctx) => {
  if (ctx.flags.includes('coup_attempted'))
    return "The tanks came at three in the morning. You hear tracked vehicles on cobblestone before you see them. You know what it is before anyone tells you.\n\nDusek called at 03:17. Her voice was steady — Irina Dusek's voice is always steady — but the speed of her words was different: 'Brenner has moved. Three armored companies approaching from the east. I need your authorization to engage.'\n\nThe authorization. The order to fire on Veltrian soldiers. I gave it. I would rather be the Chancellor who gave a terrible order than the former Chancellor too afraid to give any order.\n\nThe fighting is ongoing. My family is in a safe location. I am at my desk. I will be here until this ends.\n\nMy father said a country's character is revealed not in its laws but in the moments when its laws are broken. We are in one of those moments."
  if (ctx.flags.includes('military_rallied_reformist'))
    return "Three thousand soldiers on the parade ground. Dusek had called them — not an order, a request. She wanted to know who was willing to stand with the constitutional government. Three thousand answered.\n\nI spoke for ten minutes. I don't remember most of it. I remember the faces. The young captain whose hands were shaking. The sergeant who nodded when I talked about their oath.\n\nDusek told me afterward that the rest of the military was watching. Taking sides. The three thousand gave the wind a direction.\n\nI slept two hours on the study couch. Serida brought me coffee at four. She didn't say anything. The coffee was enough."
  return "The coup was averted. Not defeated — averted. There is a difference. Defeated means we fought and won. Averted means the people planning to fight decided not to.\n\nThe people who decided not to fight are still here. Still in the military. Still believing what they believed. They just decided tonight was not the night.\n\nDusek negotiated the stand-down personally. I don't know what she promised. She said: 'Some negotiations are better left unrecorded.' I trust her. I also wonder — will always wonder — what price was paid in my name without my permission."
},

38: (ctx) => {
  if (ctx.flags.includes('family_reckoning_resolved'))
    return "Jonas, Liora, and Tomas all in the same room tonight. The first time in months. Not the same building — the same room. Sitting. Talking. Looking at each other the way families do when they're trying to remember what they were.\n\nLiora spoke first. She said: 'I understand why you haven't been here. I don't like it. But I understand.' The most generous thing anyone has said to me this year.\n\nTomas was quieter. Near the end he said: 'I know you're trying.' Four words. He's eight.\n\nJonas spoke last: 'I'm not going anywhere.' He didn't say he was happy. He said he was staying. That is not reconciliation. It is the beginning of one."
  if (ctx.flags.includes('soren_trial_public'))
    return "Soren's trial began today. I watched from the gallery — not as Chancellor, but as the daughter of a man who spent his final years trying to prove what the court is now reading into the record.\n\nThe prosecutor read the charges. Soren did not flinch. He has had years to prepare. I have had years to imagine this moment. The reality is not as satisfying as the imagination.\n\nJustice, when it arrives, feels less like victory than exhaustion. The thing you wanted for so long is here and you realize you wanted the wanting more than the having.\n\nThe trial will continue. I will attend some of it. Not all. I have a country to run. That sounds like an excuse. It is an excuse. It is also the truth."
  return "The Soren trial is underway. The gallery is packed with families of the disappeared — waiting for years, some of them decades.\n\nI spoke with a woman in the corridor. Her son disappeared in 1959. She said: 'I don't care if he goes to prison. I just want to know where my son is buried.' The devastating modesty of that request sits with me more heavily than any political demand.\n\nShe doesn't want revenge. She wants a grave to visit.\n\nI don't know if the trial will give her that. The records were destroyed or hidden. The Halvek regime was methodical about surveillance and careless about accountability. Enough evidence to confirm crimes. Not enough to identify every victim.\n\nThat is justice under these conditions. Partial. Better than nothing. Not as good as it should be."
},

39: (ctx) => {
  if (ctx.flags.includes('act3_climax_resolved'))
    return "Everything converged today. The Tyvaren crisis, military loyalty, budget shortfall, family — each demanding a decision, each affecting the others.\n\nI acted. The decisions are made. I will find out whether they were right. The finding out is the part that keeps me awake — not the deciding, the waiting. The gap between action and outcome is where anxiety lives.\n\nTheron came after the final meeting. He said: 'I don't know if you're right. But you're not wrong the way your predecessors were wrong. You're wrong in better ways.' The most Theron thing anyone has ever said. Also the most honest assessment of leadership I've received.\n\nThe fourth act will determine whether any of this mattered."
  return "Act Three review. Theron, Dusek, and I sat in my study going over every decision, every mistake. Dusek said: 'Your military decisions have been cautious. Sometimes too cautious. But caution is better than recklessness and you have never been reckless.' Theron said: 'The constitutional framework is intact. Damaged but intact. More than I expected.'\n\nDamaged but intact. That phrase describes my Chancellorship. The country. The coalition. The family. The woman writing these words. All damaged but still here.\n\nThe final act begins next week. Everything I built and failed to build will be tested. Thirteen weeks. One quarter of a year. A lifetime in politics."
},


// ─── ACT FOUR: THE RECKONING (WEEKS 40–52) ──────────────────────────────────

40: (ctx) => {
  if (ctx.flags.includes('government_in_exile'))
    return "I am writing this in Stellamere. A borrowed office in a diplomatic annex that smells like someone else's cigarettes. Outside, the Arcturian capital goes about its business — a city that does not know or care that Veltria's legitimate government operates out of a converted conference room.\n\nBrenner's junta controls Ashenmere. The radio broadcasts martial music and statements about 'national restoration' — every junta uses the same vocabulary. Restoration. Recovery. Order. Words designed to make tyranny sound like healing.\n\nDusek's people are in the countryside. Kaelen's fighters hold the highlands. The resistance is real. But resistance is not government.\n\nTomas asked if we were ever going home. I said yes with more certainty than I felt. He needs certainty like food and sleep. I will manufacture it for him as long as I have to. That is what mothers do."
  if (ctx.flags.includes('war_path_chosen'))
    return "The war began this morning. Tyvaren forces crossed at three points — Gravenmark Pass, Korven Forest, Dravenhollow highlands. Dusek's forward positions are holding but she says they 'will not hold indefinitely.' Indefinitely means days, not weeks.\n\nI authorized full mobilization at 04:30. Within hours, ninety thousand reservists report to their units. Some will be in combat by the end of the week. Some will not come home.\n\nThe Arcturian ambassador offered 'support.' I asked what kind. He said: 'Moral support, for now. Material support depending on developments.' Depending on developments means they're watching to see who's winning.\n\nI told the nation we would defend our sovereignty. The conviction was real. The confidence was manufactured."
  return "Forty weeks since I swore to uphold the constitution. Forty weeks since I believed the arc of history bent toward justice. I still believe that. Less clearly than I did.\n\nClarity is a luxury of people who never had to govern. Governing is discovering that every principle has exceptions and every exception creates new problems.\n\nThe fourth act is beginning. The end is in sight but the path is obscured. Twelve weeks. Just enough time to fix everything or destroy everything. Probably neither. Probably something in between.\n\nThe something in between is where I live now."
},

41: (ctx) => {
  if (ctx.flags.includes('reform_implementation_begun'))
    return "Reform implementation has begun. The constitutional court is being established. I signed fourteen executive orders this morning — each a small piece of a larger transformation.\n\nKolvar called the court appointments 'a power grab disguised as reform.' He's not entirely wrong. Part of reform is, necessarily, a power grab — taking power from people who had it and giving it to people who should. The difference is whose power and why.\n\nI am moving fast because speed is the only protection against obstruction. The slower you move, the more time opponents have to organize. That is not democratic theory. It is practical governance. The theory and practice diverged around week three."
  if (ctx.tomasWellbeing > 60)
    return "Tomas gave a presentation at school today. About democracy. What his mother does. He spoke for fifteen minutes without looking at his cards. I didn't teach him that. He learned by watching me.\n\nHe said: 'I told them you were the best Chancellor Veltria ever had.' Then: 'Is that true?' I said it was too soon to know. He said: 'Mr. Renek says you're destroying the country.' The Church sends teachers to his school.\n\nIt always comes back to the Church. The Archbishop's program reaches my son's classroom and he hears things about his mother I can't control because I'm never there.\n\nI told him to listen and think and decide for himself. He said: 'I already decided.' I'm proud of him. I'm also afraid."
  return "The constitutional court's first case is a challenge to the emergency powers provision — brought by reformist lawyers who are my allies. They are suing my government. That is either healthy democracy or the end of my legislative agenda.\n\nTheron says the challenge is good: 'A constitution never tested is a constitution no one is reading.' He's right about principles. Less often right about politics. The politics are terrible — my own supporters making the case that I overreached.\n\nI'm letting the challenge proceed. I could influence the court. I appointed three of seven judges. But interfering would make me the thing I campaigned against. The line is exactly this thin."
},

42: (ctx) => {
  if (ctx.flags.includes('austerity_begun'))
    return "The IMA conditions arrived. Forty-three pages. The word 'efficiency' appears seventeen times. 'Suffering' appears zero. That ratio tells you everything.\n\nPrivatize the Grain Authority. Sell Northern Rail. Cut sixty thousand jobs. The document calls these 'structural adjustments necessary for fiscal sustainability' — a euphemism. The plain translation: make your people poorer so investors feel safer.\n\nI have three options. Accept and lose the coalition. Reject and default. Negotiate — finding a third path in a binary world. I am negotiating. I don't know if it will work.\n\nSome moments in governing, the right thing is clear and the hard thing is doing it. Other moments, nothing is clear and everything is hard."
  if (ctx.flags.includes('war_phase_one_complete'))
    return "Phase one is over. Gravenmark Pass holds. Korven Forest contested. Dravenhollow highlands holding with Kaelen's fighters. Two thousand dead. Four thousand wounded. Numbers preliminary — the final count will be worse.\n\nI spent the evening drafting letters to the fallen. Each letter a small failure of language. No words make a death acceptable. Only words that acknowledge what was lost and why the loss is not meaningless.\n\nThe Tyvaren advance has stalled. Not retreated — stalled. Dusek says we have six to eight weeks before the next phase. The question is whether we have enough resources.\n\nThe Krone is falling. The international community watches but doesn't intervene. We are alone. We have always been alone. Now we can measure the aloneness in casualty figures."
  return "The war continues. The map pins haven't moved in three days — a stalemate Dusek calls 'tactically advantageous' and I call waiting. The waiting is the hardest part.\n\nI visited a field hospital. Soldiers, eighteen years old. Boys who hadn't held rifles before mobilization. They looked at me the way people look when they want you to tell them what they did mattered. I told them it mattered. I believed it. I also believed gratitude is not enough. It's never enough.\n\nOne asked if we would win. I said yes with more certainty than I felt. The certainty is manufactured. The conviction is real. The difference is the difference between leadership and theater."
},

43: (ctx) => {
  if (ctx.marriageHealth > 60)
    return "Jonas made coffee for two this morning. He didn't say anything — just put the second cup next to my briefing books. That small, domestic, ordinary gesture was the most intimate thing between us in months.\n\nTwenty years of marriage. I know the shape of his silences and the meaning of his coffee. Two cups means: I am still here. Not making a speech about it. But still here.\n\nThe coffee was too hot and too bitter and exactly what I needed. I didn't say thank you. He knows.\n\nThat marriage — the one where we had time for dinner and arguments about the garden — is gone. But something quieter is growing. Something that doesn't need as much time because it has learned to be efficient with the time it has.\n\nMaybe that's what long marriages become. Saying everything with a second cup of coffee."
  if (ctx.flags.includes('family_estranged_path'))
    return "Liora communicates through notes now. Left on the kitchen counter. Short messages about her schedule, things she needs signed. The notes are polite. Impersonal. She has learned to write like a staffer. She has learned to protect herself from me.\n\nI knocked on her door at nine. She opened it enough to see who it was. Not all the way. She said she was studying. I said we could talk later. She said okay. The okay was dismissal.\n\nI stood in the hallway for a long time. She was fifteen feet away. The distance wasn't physical.\n\nI know what she wants. Time. Presence. The attention I give to the country. I don't know how to give it to her without failing at other things. Twenty million people. One fifteen-year-old girl. I can't do both."
  return "The family is holding. Not thriving — holding. Jonas is here. Liora speaks to me. Tomas leaves his school projects on my desk. A clay model of the Chancellery — lopsided. He said it was intentional: 'Because the building feels lopsided, Mama.' He notices things.\n\nI put the model next to my father's photograph and the intelligence briefings. The model is the most important thing on the desk. It reminds me there is a version of this building in my son's imagination — lopsided, where his mother works and comes home late and forgets permission slips.\n\nI signed the permission slips tonight. All of them. Even the ones from two weeks ago. The signature wasn't for the school. It was for Tomas."
},

44: (ctx) => {
  if (ctx.flags.includes('civilian_front_managed'))
    return "Sixty thousand civilians displaced. Bread shortages in three weeks. The war is no longer at the border. It is in the kitchens and the bakeries and the queues.\n\nI met with the National Supply Committee today. The numbers are worse than last week and last week they were unacceptable. Grain reserves at thirty-one percent. Fuel at forty-four. Medicine at twenty-two.\n\nThe committee asked for guidance. I gave them numbers and targets and the kind of decisive language leaders use when they don't have enough information. The language was convincing. The information was not.\n\nAfter the meeting, I sat alone in my office and stared at the ceiling. I don't know how long. Long enough for the coffee to go cold."
  if (ctx.flags.includes('counter_coup_military'))
    return "We returned to Veltrian soil tonight. A fishing vessel from the southern coast. The textile mill outside Kravenstal is our headquarters now — not a Chancellery, but a command post. Dusek's loyalists have secured the surrounding district.\n\nI addressed the resistance leaders at midnight. Thirty-seven people in a room built for twenty. The air smelled of wool and diesel and hope — the last one was the faintest.\n\nThe counter-offensive begins at dawn. Brenner holds Ashenmere but the countryside is not his. The countryside has never been anyone's for long. Veltria is a country that resists ownership. I am counting on that. I am betting my country on a metaphor."
  return "The reform backlash is real. Kolvar, Brenner, Renek, the business class — all pushing back simultaneously. The coalition that passed the constitution is now the coalition trying to dismantle it.\n\nI have two options: compromise or crush. Compromise means watering down provisions I spent months negotiating. Crush means using executive power in ways that look exactly like what the opposition accuses me of.\n\nTheron says: 'The constitution was not designed to survive a hostile Assembly. It was designed to constrain one.' I asked if it would hold. He said: 'It will hold as long as we do.'\n\nWe. Not the document. Us. The people defending it."
},

45: (ctx) => {
  if (ctx.flags.includes('reform_backlash_resolved'))
    return "The backlash has crested. Kolvar's coalition is fracturing — the Church and the military are uncomfortable bedfellows. Brenner sent an emissary today. He wants to talk. Not negotiate — talk. The difference is subtle. It is also encouraging.\n\nSix provisions survived intact. Four were modified. Two were shelved — not killed, but postponed. The postponement feels like defeat dressed as patience.\n\nTheron says: 'Compromise is not surrender. It is the recognition that you can't win everything at once.' I know he's right. I also know that the two shelved provisions were the ones Kaelen cared about most.\n\nI called Kaelen tonight. He was quiet. Then he said: 'Postponement is not the same as abandonment. I will wait. We are very good at waiting.'\n\nThe Dravenni are good at waiting. They have had centuries of practice."
  return "The workers are striking. The railways stopped at noon. The ports are idle. The steel mills are silent. Soraya Khaled called it 'a necessary demonstration of the people's power.' She wants me to side with the strikers. Vostane's successor wants me to break the strike.\n\nThere is no middle position when the country is at war and workers demand better conditions while soldiers demand more ammunition. Both demands are legitimate. Both demands cannot be met simultaneously.\n\nI addressed the nation tonight. I asked for patience and unity. The words were correct. The audience was divided. Half the country heard a plea for solidarity. Half heard a Chancellor who couldn't choose."
},

46: (ctx) => {
  if (ctx.flags.includes('decisive_battle_fought'))
    return "The decisive engagement at Gravenmark is underway. Every military decision of the past forty-six weeks converges here. Dusek is in the field command post — not the Chancellery, not the Ministry. The field. Where the maps are marked in grease pencil and the reports come in by radio.\n\nI have not slept. The phone rings every twenty minutes with updates. 'Forward elements engaged.' 'Left flank holding.' 'Reserves committed.' Each phrase is a translation. Behind each phrase are soldiers whose names I will learn when the casualty lists arrive.\n\nTomas asked me this morning if we were winning. I said yes. He said: 'What happens if we lose?' I told him we wouldn't. I told him with certainty I did not feel. The certainty is for him. The uncertainty is mine."
  if (ctx.flags.includes('tomas_engaged'))
    return "Tomas asked to meet at the park. He was wearing the sweater I gave him two years ago. He had something to say. He's been rehearsing.\n\nHe told me about the Iron Covenant recruiter. The one who approached him at the switching yards months ago. He told me he hadn't gone back. He told me he didn't believe the things they said about me. Then he asked: 'Are you a good person, Mama?'\n\nI said I was trying very hard to be. He said: 'I think you are. But I wanted to hear you say it.'\n\nWe sat on the bench for another hour. We didn't talk about politics. We talked about football and school and whether he could have a dog. Normal things. The things I should have been talking about for forty-six weeks.\n\nHe's nine. He has more courage than half the people in my cabinet."
  return "The diplomatic endgame is approaching. The International Forum has offered formal mediation. Both the Arcturians and Orythians have endorsed the proposal — meaning both see advantage in being seen as peacemakers.\n\nThe terms will be brutal. Vukov will demand concessions. The international community will demand compromises. The opposition will demand my resignation. Everyone will demand something and I will give some of what they demand and refuse the rest. The ratio will determine whether the peace holds.\n\nI keep thinking about my father's definition of peace: 'Not the absence of conflict. The presence of a process for resolving it without violence.' We are building that process. Whether it works depends on people who are not me."
},

47: (ctx) => {
  if (ctx.flags.includes('new_order_established'))
    return "The final reform bill passed today. Fifty-six percent. Twenty-three of thirty-five provisions implemented. The old order is functionally dead. What grows in its place depends on the next twelve months.\n\nTheron came to my office after the vote. He looked older than he did this morning. He said: 'We did something that will outlast us.' I asked if he was satisfied. He said: 'I am never satisfied. But I am less unsatisfied than I was.' That is the most Theron statement possible.\n\nThe constitution exists. The institutions are being built. The country is not utopia — it is not even particularly functional. But it has rules now. Rules that apply to the powerful as well as the powerless. That was the promise. I kept it."
  if (ctx.flags.includes('dark_path_chosen'))
    return "I authorized measures tonight that I cannot write about. The authorization is on a separate document in a separate drawer. This diary is not that document.\n\nSome decisions are made in rooms so dark that the light of ordinary language cannot reach them. You make them because you believe the alternative is worse. You believe that. You have to. The believing is what lets you sleep. I did not sleep.\n\nMy father would not have recognized the person who signed those papers. I am not sure I recognize her either. But the signature is mine. The consequences are mine. The judgment — whenever it comes, from whomever — will be mine alone.\n\nI am not writing this for absolution. I am writing it because someone should know that I knew what I was doing. That I chose it. That it was a choice."
  return "The new order is taking shape. Not the one I campaigned on — that one was cleaner, simpler, built from principles that didn't account for Tyvaren invasions and coup attempts and economic collapses. The actual new order is messier. More compromised. But it exists.\n\nI addressed the Assembly today. I talked about resilience and pragmatism. I did not talk about the things I gave up to get here. The things I gave up are in this diary.\n\nThe opposition spoke after me. Kolvar called my government 'a transition that forgot to end.' The phrase is clever. It is also true in a way he didn't intend. Transitions end when the new system is stable. Veltria is not stable yet. But it is more stable than it was. The direction is correct. The pace is insufficient. Both things are true."
},

48: (ctx) => {
  if (ctx.flags.includes('war_victory'))
    return "The war is over. Veltria endured. Eight thousand dead. Fourteen thousand wounded. Four hundred million ₭ in damage. The numbers are numbers. Behind them are families I will spend the rest of my life trying to honor with words that always feel insufficient.\n\nThe armistice was signed at noon. Vukov's signature is on the document next to mine. I looked at his face across the table. He looked at mine. Neither of us said anything. The silence was the closest thing to acknowledgment we will ever share.\n\nDusek came to my office tonight. She was still in her field uniform. She said: 'We held.' I said: 'You held.' She said: 'You gave the orders that made holding possible.' I don't know if that's true. I know she believes it. Tonight that is enough."
  if (ctx.flags.includes('war_defeat'))
    return "The armistice was signed today. The terms are not victory. The terms are survival. Gravenmark Pass is no longer Veltrian territory. The indemnity will take a generation to pay. The military will be reduced to a fraction of its former size.\n\nI signed the document. My hand was steady. The steadiness was not courage. It was the absence of alternatives.\n\nI addressed the nation tonight. I told them we had lost the war but preserved the Republic. I told them the constitution remained in force. I told them democracy was stronger than defeat. I believed parts of what I said. The parts I didn't believe I said more loudly.\n\nHistory will judge whether I should have fought harder or surrendered sooner. I made the call I could live with. The call and the living-with are not the same thing."
  return "The armistice negotiations are complete. The terms are neither victory nor defeat — the gray space where most wars actually end. Borders redrawn. Forces reduced. International monitors stationed in the border regions.\n\nI briefed the cabinet this evening. Some were relieved. Some were angry. Most were too exhausted to be either. The exhaustion is the signature emotion of this Chancellorship.\n\nThe country will rebuild. The economy will recover. The people will eventually stop waking up at night thinking about air raid sirens. Eventually. The 'eventually' is doing a lot of work."
},

49: (ctx) => {
  if (ctx.marriageHealth > 60)
    return "Jonas and I walked through the palace gardens tonight. No phone. No briefings. No aides. He held my hand. We talked about nothing important. It was the most important conversation we've had in months.\n\nThe flowers are gone — winter. But the roots are underground. Waiting. That's what a marriage is. Not the flowers. The roots.\n\nHe didn't ask how I was. He didn't need to. Twenty years. You stop needing to ask.\n\nLiora came home for dinner. She brought her new project — something she's been working on for months. She showed me the sketches. I didn't understand all of them. I told her I was proud. She said: 'I know.' She used to say 'really?' The change is small. It means something."
  if (ctx.flags.includes('jonas_left'))
    return "The divorce papers arrived today. In an envelope with my name in his handwriting. He filed them without telling me. I found out from my chief of staff, who found out from the court clerk, who found out because someone leaked it to the press.\n\nI called Jonas. He answered. I asked if it was true. He said: 'I've been telling you it was true for a year. You weren't listening.'\n\nHe was right. I wasn't listening. I was governing. I was negotiating. I was fighting a war and managing an economy and trying to hold a country together. I thought that was enough. I thought the marriage would wait. Marriages don't wait. They atrophy. Mine atrophied while I was in briefings.\n\nTwenty-three years. Over. Not with a fight — we had those. Not with silence — we had that too. Just... over. The way things end when you're not paying attention."
  return "Three weeks remain. I have started saying goodbye to this office in small ways. Touching the desk. Looking out the window longer than necessary. Noticing things I've walked past every day without really seeing.\n\nThe palace at night is different. The silence is not empty. It's full of everything that happened here.\n\nThe reelection question has been asked. The party wants to know if I'll stand. Running means defending my record. Not running means someone else defines it.\n\nI haven't decided. I have until Friday. I have a country to run until Friday. The country doesn't care about my decision. The country just needs to be governed."
},

50: (ctx) => {
  if (ctx.publicOrder > 55)
    return "The streets are quiet. Not the quiet of repression — I remember that from Halvek. The quiet of a people at peace. I am not naive enough to think it will last.\n\nI submitted the final budget review with my signature, not my stamp. Some things deserve a personal touch. I wanted whoever reads it in fifty years to know a specific person made these decisions.\n\nThat is the thing about power. It feels abstract when you don't have it. When you have it, you realize it is the most personal thing in the world.\n\nTwo weeks remain."
  return "Two weeks. My staff has started archiving records. Preparing for transition — whichever direction. Some look at me differently. Like they're already saying goodbye.\n\nI'm not ready. I'm never ready. That's what I learned this year — no one is ever ready. You do things because they need to be done and hope you did them well enough. 'Well enough' is not 'perfectly' but it is sometimes the best that was possible.\n\nI hope my legacy is more than 'she tried.' I hope it is 'she did what she said, mostly, and the country is better.'\n\nWe'll find out in two weeks."
},

51: (ctx) => {
  if (ctx.economyHealth > 10)
    return "Last full week. The economy is stronger than when I started. Vostane's final quarterly report — twenty-two pages. On page twenty-two, at the bottom, she wrote something she has never written: 'Recommendation: continue current trajectory.'\n\nI put the report in the drawer I will take with me. That sentence belongs in my personal archive. It is the only award I have ever received from Elara Vostane. Also the only one that matters.\n\nI walked through the palace tonight — the long route, past the portraits. Some governed well. Some poorly. All had a last full week. All wondered if they'd done enough.\n\nI wonder that now. I will probably wonder it for the rest of my life. But I am sure of more things than I was a year ago. That's not nothing. That's everything."
  return "Last full week. I walked through the palace past the portraits of Chancellors who came before me. I stopped in front of Marek — considered a failure in his lifetime, kinder to him in history. I wonder which way the judgment will go for me.\n\nTomas did his homework at the kitchen table tonight. Liora said 'goodnight' and meant it. Jonas made coffee for two without being asked. Something survived. Despite everything. Something survived.\n\nThe election is next week. Or the succession. Or whatever comes after. The country will decide. Then I will sleep."
},

52: () =>
"Fifty-two weeks. One year.\n\nI have kept this diary through a war scare and constitutional revision, economic crisis and recovery, family strain and small reconciliations. I have made mistakes — some serious, some I won't realize were mistakes for years. I have also done things I am proud of. Things my children will read about. Things my father, wherever he is, would have understood.\n\nI opened these pages as someone just given the most powerful office in the Republic. I am closing them as someone who understands that power is not a possession. It is a loan. From the people. For a limited time. With conditions you do not get to negotiate.\n\nThis is the last entry. Whatever happens tomorrow — the election, the counting, the concession or the victory — this year will always be what it was: the year I learned what power costs and what democracy demands and who I am when the lights go out.\n\nTomorrow, Veltria decides.\n\nTonight, I sleep.\n\nI think.",

}

